// input: the protocol tests of the input family (docs/PROTOCOLS.md section 9.6), the port of
// core/tests/input: the three instantiations of upstream's InputBaseState<M> (InputState,
// EditorState, TextareaState, generated by the `[instantiate] states` rule), OtpState, their
// events, reads, buffered writes and calls that return a value, and every handler shape the
// family's elements take. Each mode runs offscreen (the diag library) under a gk-meter script and
// prints lines that core/tests/go/run-input.sh checks, with the exit code.
//
//	GK_PROTO=input | calls | number | otp | paste | released-editor | call-in-view | providers |
//	         links
//
// The providers mode (the editor's providers and the styled code editor) is in providers.go.
package main

import (
	"fmt"
	"log"
	"os"
	"strconv"

	"github.com/ibanks42/goui-kit/gk"
	gkeditor "github.com/ibanks42/goui-kit/gk/editor"
	"github.com/ibanks42/goui-kit/gk/s"
	"github.com/ibanks42/goui-kit/gk/theme"
)

type App struct {
	mode   string
	root   gk.View
	input  gkeditor.InputState
	text   gkeditor.TextareaState
	editor gkeditor.State
	number gkeditor.InputState
	otp    gkeditor.OtpState
	focus  gk.FocusHandle
	subs   [4]gk.Subscription
	frame  int
	last   gk.Range
	events int
	steps  int
	pastes int
	gone   bool         // the editor was released (released-editor)
	asks   gk.RowSource // the editor's providers (providers)
	asked  int
}

// The checks expect an enum value printed by its name.
var (
	stepNames = map[gkeditor.StepAction]string{gkeditor.StepActionIncrement: "Increment", gkeditor.StepActionDecrement: "Decrement"}
	otpNames  = map[gkeditor.OtpEvent]string{gkeditor.OtpEventChange: "Change", gkeditor.OtpEventComplete: "Complete", gkeditor.OtpEventFocus: "Focus", gkeditor.OtpEventBlur: "Blur"}
)

// --- events -------------------------------------------------------------------------------------

func (a *App) inputEvent(cx *gk.Cx, e gkeditor.InputEvent) {
	a.events++
	switch v := e.(type) {
	case gkeditor.InputEventChange:
		fmt.Printf("input change value=%q cursor=%d\n", a.input.Value(cx), a.input.Cursor(cx))
	case gkeditor.InputEventPressEnter:
		fmt.Printf("input enter secondary=%v shift=%v value=%q\n", v.Secondary, v.Shift, a.input.Value(cx))
	case gkeditor.InputEventFocus:
		fmt.Println("input focus")
	case gkeditor.InputEventBlur:
		fmt.Println("input blur")
	}
}

func (a *App) textEvent(cx *gk.Cx, e gkeditor.InputEvent) {
	if _, ok := e.(gkeditor.InputEventChange); ok {
		fmt.Printf("textarea change value=%q multi=%v\n", a.text.Value(cx), a.text.IsMultiLine(cx))
	}
}

func (a *App) editorEvent(cx *gk.Cx, e gkeditor.InputEvent) {
	if _, ok := e.(gkeditor.InputEventChange); ok {
		fmt.Printf("editor change value=%q code=%v\n", a.editor.Value(cx), a.editor.IsCodeEditor(cx))
	}
}

func (a *App) numberEvent(cx *gk.Cx, e gkeditor.InputEvent) {
	if _, ok := e.(gkeditor.InputEventChange); ok {
		fmt.Printf("number change value=%q\n", a.number.Value(cx))
	}
}

func (a *App) otpEvent(cx *gk.Cx, e gkeditor.OtpEvent) {
	fmt.Printf("otp event=%s value=%q\n", otpNames[e], a.otp.Value(cx))
}

// The handler shape (StepAction) -> () of base::NumberInput::on_step.
func (a *App) stepped(cx *gk.Cx, e gkeditor.StepAction) {
	a.steps++
	fmt.Printf("number step action=%s n=%d\n", stepNames[e], a.steps)
	v, _ := strconv.Atoi(a.number.Value(cx))
	by := -2
	if e == gkeditor.StepActionIncrement {
		by = 2
	}
	a.number.SetValue(cx, fmt.Sprintf("%d", v+by))
	fmt.Printf("number value=%q\n", a.number.Value(cx)) // a read sends the write first
}

// The handler shape (ClipboardItem) -> bool of Input::on_paste: false lets the input paste.
func (a *App) pasted(cx *gk.Cx, item gk.ClipboardItem) bool {
	a.pastes++
	text := ""
	for _, e := range item.Entries {
		if s, ok := e.(gk.ClipboardEntryString); ok {
			text = s.Text
		}
	}
	fmt.Printf("input paste n=%d entries=%d text=%q\n", a.pastes, len(item.Entries), text)
	return false
}

// The handler shape (&str, &ClickEvent) of TextView::on_link_click (its payload type is named by
// the generator after its shape number), and the click of an InputGroupButton.
func (a *App) linkClicked(cx *gk.Cx, e gk.Event83) {
	a.events++
	fmt.Printf("link clicked url=%q button=%v\n", e.A0, e.A1.Button)
}

func (a *App) groupClicked(cx *gk.Cx, e gk.ClickEvent) {
	a.events++
	fmt.Printf("group button clicked count=%d\n", e.ClickCount)
}

func (a *App) linksView(cx *gk.Cx) gk.Element {
	return gk.VFlex(s.SizeFull, s.P4, s.Gap2).Bg(theme.Background).TextColor(theme.Foreground).
		Child(gk.Div().W(gk.Px(300)).Child(gkeditor.TextViewMarkdown("md", "see [the link](https://example.com/x) here").OnLinkClick(a.linkClicked))).
		Child(gk.Div().W(gk.Px(300)).Child(gkeditor.InputGroup("g").Input(gkeditor.Input(a.input)).
			Addon(gkeditor.InputGroupAddon("a").Child(gkeditor.InputGroupButton("go").Label("Go").OnClick(a.groupClicked)))))
}

func (a *App) focusAway(cx *gk.Cx, e gk.MouseEvent) {
	gk.Focus(cx, a.focus)
}

// The selection is not an event upstream: a frame handler reports it when it changes.
func (a *App) watch(cx *gk.Cx) {
	a.frame++
	r := a.input.SelectedRange(cx)
	if r != a.last {
		a.last = r
		fmt.Printf("input selection lo=%d hi=%d text=%q reversed=%v\n", r.Lo, r.Hi, a.input.SelectedValue(cx), a.input.IsSelectionReversed(cx))
	}
}

// --- calls: reads, buffered writes, updates that return a value -----------------------------------

func (a *App) calls(cx *gk.Cx) {
	a.frame++
	if a.frame == 3 {
		fmt.Printf("calls lease later value=%q\n", a.input.Value(cx))
	}
	if a.frame != 2 {
		return
	}
	// InputState: a write is buffered; a read sends it first, so it sees it.
	a.input.SetValue(cx, "abc def")
	a.input.SetSelectedRange(cx, gk.Range{Lo: 0, Hi: 3})
	r := a.input.SelectedRange(cx)
	fmt.Printf("calls input value=%q selected=%d..%d text=%q single=%v multi=%v\n",
		a.input.Value(cx), r.Lo, r.Hi, a.input.SelectedValue(cx), a.input.IsSingleLine(cx), a.input.IsMultiLine(cx))
	a.input.Insert(cx, "X") // at the cursor, the end of the selection
	fmt.Printf("calls input insert value=%q cursor=%d\n", a.input.Value(cx), a.input.Cursor(cx))
	a.input.SetSelectedRange(cx, gk.Range{Lo: 0, Hi: 3})
	a.input.Replace(cx, "Y") // the selection
	fmt.Printf("calls input replace value=%q cursor=%d\n", a.input.Value(cx), a.input.Cursor(cx))
	a.input.SelectAll(cx)
	r = a.input.SelectedRange(cx)
	fmt.Printf("calls input select_all %d..%d\n", r.Lo, r.Hi)
	a.input.SetDisabled(cx, true)
	fmt.Printf("calls input editable=%v\n", a.input.IsEditable(cx))
	a.input.SetDisabled(cx, false)

	// TextareaState: multi-line, searchable; search calls return a value at once.
	a.text.SetValue(cx, "one two\none three")
	fmt.Printf("calls textarea multi=%v single=%v value=%q\n", a.text.IsMultiLine(cx), a.text.IsSingleLine(cx), a.text.Value(cx))
	a.text.SetSearchQuery(cx, "one", false)
	if mr, ok := a.text.NextSearchMatch(cx).Get(); ok {
		fmt.Printf("calls textarea next_match %d..%d\n", mr.Lo, mr.Hi)
	} else {
		fmt.Println("calls textarea next_match none")
	}
	n := a.text.ReplaceAllSearchMatches(cx, "1")
	fmt.Printf("calls textarea replaced=%d value=%q\n", n, a.text.Value(cx))

	// EditorState: the code editor mode, without grammars.
	a.editor.SetLineNumber(cx, true)
	a.editor.SetValue(cx, "fn main() {\n    let x = 1;\n}\n")
	fmt.Printf("calls editor code=%v multi=%v language=%q value=%q\n",
		a.editor.IsCodeEditor(cx), a.editor.IsMultiLine(cx), a.editor.LanguageName(cx), a.editor.Value(cx))

	// A read of a state on lease reports busy through Try; a write from there lands later.
	inside := gk.NewHandler(func(cx *gk.Cx) bool {
		_, ok := a.input.TryValue(cx)
		fmt.Printf("calls lease busy=%v\n", !ok)
		a.input.SetValue(cx, "after the lease")
		return true
	})
	ret := gk.TestFireInUpdate(cx, a.input, inside)
	fmt.Printf("calls lease ret=%d value=%q\n", ret, a.input.Value(cx))
	fmt.Println("calls done")
}

// --- the view -----------------------------------------------------------------------------------

func (a *App) init(cx *gk.Cx) {
	a.input = gkeditor.NewInputState(cx).Placeholder("Name").Build()
	a.text = gkeditor.NewTextareaState(cx).AutoGrow(2, 4).Searchable(true).Build()
	a.editor = gkeditor.NewState(cx).Language("rust").Build()
	a.number = gkeditor.NewInputState(cx).Min(0).Max(10).Step(float64(2)).DefaultValue("4").Build()
	a.otp = gkeditor.NewOtpState(cx, 4).Build()
	a.focus = gk.NewFocusHandle(cx)
	a.subs[0] = a.input.OnInputEvent(cx, a.inputEvent)
	a.subs[1] = a.text.OnInputEvent(cx, a.textEvent)
	a.subs[2] = a.editor.OnInputEvent(cx, a.editorEvent)
	a.subs[3] = a.number.OnInputEvent(cx, a.numberEvent)
	a.otp.OnOtpEvent(cx, a.otpEvent)
	switch a.mode {
	case "input", "paste":
		gk.OnFrame(cx, a.watch)
	case "calls":
		gk.OnFrame(cx, a.calls)
	case "released-editor":
		gk.OnFrame(cx, func(cx *gk.Cx) {
			a.frame++
			if a.frame == 2 {
				gk.Release(cx, a.editor) // the view below still shows it
				fmt.Println("input released-editor released")
			}
		})
	case "providers":
		a.providersInit(cx)
	}
}

func (a *App) rootView(cx *gk.Cx) gk.Element {
	if a.mode == "call-in-view" {
		a.text.ReplaceAllSearchMatches(cx, "x") // a view may not update kit state
	}
	input := gkeditor.Input(a.input)
	if a.mode == "paste" {
		input = input.OnPaste(a.pasted)
	}
	// The styled editor (with the providers' menus) in mode providers, the generated base::Editor
	// otherwise.
	var editor gk.Element
	if a.mode == "providers" {
		editor = gkeditor.CodeEditor(a.editor, gkeditor.CodeEditorOptions{Height: 90})
	} else {
		editor = gkeditor.BaseEditor(a.editor)
	}
	// base::NumberInput: its buttons call on_step, which replaces upstream's own stepping, so
	// the handler steps the value itself.
	number := gkeditor.BaseNumberInput(a.number).Input(gkeditor.BaseInput(a.number)).OnStep(a.stepped)
	return gk.VFlex(s.SizeFull, s.P4, s.Gap2).Bg(theme.Background).TextColor(theme.Foreground).
		Child(gk.Div().W(gk.Px(240)).Child(input)).
		Child(gk.Div().W(gk.Px(240)).Child(gkeditor.Textarea(a.text))).
		Child(gk.Div().W(gk.Px(400)).H(gk.Px(90)).Child(editor)).
		Child(gk.Div().W(gk.Px(200)).Child(number)).
		Child(gkeditor.OtpInput(a.otp)).
		Child(gk.Div().W(gk.Px(120)).H(gk.Px(24)).Bg(gk.HSLA(0.6, 0.5, 0.4, 1)).TrackFocus(a.focus).
			OnMouseDown(gk.MouseButtonLeft, a.focusAway))
}

func (a *App) start(cx *gk.Cx) {
	render := a.rootView
	if a.mode == "links" {
		render = a.linksView
	}
	a.root = gk.NewView(a.init, render)
	gk.OpenWindow(cx, "input", 640, 480, a.root)
}

// Positions in the 640 x 480 window, from a shot of the first frame (GK_SHOT=1 writes it):
// the input at y 16..48, the textarea 56..114, the editor 122..212, the number input 220..252
// (base::NumberInput: its buttons have no content without the decorate closures, which are not
// bound, so up and down step it), the OTP boxes 260..292 from x 242, the block 300..324.
const (
	inputClick  = "click 60 32\n"
	away        = "click 60 312\n"
	numberClick = "click 20 232\n" // the base number input's text: up and down step it
	otpClick    = "click 258 276\n"
	editorClick = "click 200 150\n"
	linkClick   = "click 70 26\n" // mode links: the link's text, then the input group's button
	groupButton = "click 41 66\n"
)

func main() {
	a := &App{mode: os.Getenv("GK_PROTO")}
	script := "size 640 480\nframe\n"
	_, wantShot := os.LookupEnv("GK_SHOT")
	if wantShot {
		script += "shot input-" + a.mode + ".png\n"
	}
	switch a.mode {
	case "input":
		// focus, typing, select all, copy, move to the end, paste, undo, redo, enter, blur
		script += inputClick + "type hello\n" + "key ctrl-a\n" + "key ctrl-c\n" + "key end\n" + "key ctrl-v\n" +
			"key ctrl-z\n" + "key ctrl-y\n" + "key shift-left\n" + "key shift-left\n" + "key enter\n" + away + "frame\nstat\n"
	case "paste":
		script += inputClick + "type ab\n" + "key ctrl-a\n" + "key ctrl-c\n" + "key end\n" + "key ctrl-v\n" + "frame\nstat\n"
	case "calls", "released-editor", "call-in-view":
		script += "frame\nframe\nframe\nstat\n"
	case "number", "step-shape":
		script += numberClick + "key up\n" + "key up\n" + "key down\n" + "frame\nstat\n"
	case "providers":
		// a completion asked by the trigger character, answered, the first item taken by
		// enter; then the pointer rests on the text for the hover
		shot := ""
		if wantShot {
			shot = "shot input-providers.png\n"
		}
		script += editorClick + "type a.\n" + "frame\n" + shot + "key enter\n" + "move 40 135\n" + "sleep 800\nframe\nsleep 300\nframe\n" + "frame\nstat\n"
	case "links":
		script += linkClick + groupButton + "frame\nstat\n"
	case "otp":
		script += otpClick + "type 1234\n" + away + "frame\nstat\n"
	}
	if err := gk.RunHeadless(script, a.start); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("input done mode=%s events=%d steps=%d pastes=%d frame=%d asked=%d\n", a.mode, a.events, a.steps, a.pastes, a.frame, a.asked)
}
